// Unicode 16 UCD data, generated by ucd-generate 0.3.1 and distributed with
// regex-syntax 0.8.12. Its Unicode data license is adjacent to these tables.
mod case_folding_simple;
#[allow(dead_code)]
mod perl_decimal;
#[allow(dead_code)]
mod perl_space;
mod perl_word;

pub(super) fn folded(c: char) -> &'static [char] {
    let table = case_folding_simple::CASE_FOLDING_SIMPLE;
    table
        .binary_search_by_key(&c, |row| row.0)
        .ok()
        .map_or(&[], |i| table[i].1)
}
pub(super) fn contains(ranges: &[(char, char)], c: char) -> bool {
    ranges
        .get(ranges.partition_point(|&(_, end)| end < c))
        .is_some_and(|&(start, _)| start <= c)
}
pub(crate) fn punctuation_or_symbol(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_punctuation();
    }
    contains(general_category::PUNCTUATION, c) || contains(general_category::SYMBOL, c)
}
pub(crate) fn letter_mark_or_number(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_alphanumeric();
    }
    contains(general_category::LETTER, c)
        || contains(general_category::MARK, c)
        || contains(general_category::NUMBER, c)
}
pub(super) fn word(c: char, ascii_only: bool) -> bool {
    if c.is_ascii() {
        return c.is_ascii_alphanumeric() || c == '_';
    }
    !ascii_only && contains(perl_word::PERL_WORD, c)
}
pub(super) fn decimal(c: char) -> bool {
    contains(perl_decimal::DECIMAL_NUMBER, c)
}
pub(super) fn space(c: char) -> bool {
    contains(perl_space::WHITE_SPACE, c)
}

mod age;
mod general_category;
mod grapheme_cluster_break;
mod property_bool;
mod property_names;
mod property_values;
mod script;
mod script_extension;
mod sentence_break;
mod word_break;
pub(super) fn folds() -> &'static [(char, &'static [char])] {
    case_folding_simple::CASE_FOLDING_SIMPLE
}
pub(super) fn perl(key: char) -> &'static [(char, char)] {
    match key {
        'w' => perl_word::PERL_WORD,
        'd' => perl_decimal::DECIMAL_NUMBER,
        _ => perl_space::WHITE_SPACE,
    }
}
fn normalize(name: &str) -> String {
    let mut v = name
        .bytes()
        .filter(|c| !matches!(c, b'_' | b'-' | b' '))
        .map(|c| char::from(c.to_ascii_lowercase()))
        .collect::<String>();
    if v != "isc" && v.starts_with("is") {
        v.drain(..2);
    }
    v
}
fn lookup<T: Copy>(table: &[(&str, T)], key: &str) -> Option<T> {
    table
        .binary_search_by(|row| row.0.cmp(key))
        .ok()
        .map(|i| table[i].1)
}
use super::sets::Set;
type Ranges = &'static [(char, char)];
fn value(kind: &str, name: &str) -> Option<&'static str> {
    lookup(lookup(property_values::PROPERTY_VALUES, kind)?, name)
}
fn category(name: &str) -> Option<Set> {
    match name {
        "any" => Some(Set::ranges(vec![(0, 0x10ffff)])),
        "ascii" => Some(Set::ranges(vec![(0, 127)])),
        "assigned" => Some(Set::chars(general_category::UNASSIGNED).complement()),
        _ => lookup(general_category::BY_NAME, value("General_Category", name)?).map(Set::chars),
    }
}
const NAMED_CLASSES: &[(&str, (&str, &[(&str, Ranges)]))] = &[
    ("Grapheme_Cluster_Break", ("Grapheme_Cluster_Break", grapheme_cluster_break::BY_NAME)),
    ("Script", ("Script", script::BY_NAME)),
    ("Script_Extensions", ("Script", script_extension::BY_NAME)),
    ("Sentence_Break", ("Sentence_Break", sentence_break::BY_NAME)),
    ("Word_Break", ("Word_Break", word_break::BY_NAME)),
];

fn named(kind: &str, name: &str) -> Option<Set> {
    match kind {
        "General_Category" => category(name),
        "Age" => through_age(name),
        _ => {
            let (namespace, table) = lookup(NAMED_CLASSES, kind)?;
            lookup(table, value(namespace, name)?).map(Set::chars)
        }
    }
}

fn through_age(name: &str) -> Option<Set> {
    let rank = |s: &str| {
        let (a, b) = s.strip_prefix('V')?.split_once('_')?;
        Some((a.parse::<u8>().ok()?, b.parse::<u8>().ok()?))
    };
    let max = rank(value("Age", name)?)?;
    let mut pairs = vec![];
    for &(name, ranges) in age::BY_NAME {
        if rank(name)? <= max {
            pairs.extend(ranges.iter().map(|&(a, b)| (a as u32, b as u32)))
        }
    }
    Some(Set::ranges(pairs))
}
pub(super) fn property(query: &str) -> Option<Set> {
    if let Some((k, v)) = query.split_once([':', '=']) {
        return named(
            lookup(property_names::PROPERTY_NAMES, &normalize(k))?,
            &normalize(v),
        );
    }
    let v = normalize(query);
    if let Some(name) = lookup(property_names::PROPERTY_NAMES, &v)
        && let Some(ranges) = lookup(property_bool::BY_NAME, name)
    {
        return Some(Set::chars(ranges));
    }
    category(&v).or_else(|| named("Script", &v))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn word_class_agrees_with_unicode_ranges_and_ascii_mode_for_every_scalar() {
        let mut ranges = perl_word::PERL_WORD.iter().peekable();
        for c in (0..=u32::from(char::MAX)).filter_map(char::from_u32) {
            while ranges.next_if(|range| range.1 < c).is_some() {}
            let unicode = ranges.peek().is_some_and(|range| range.0 <= c);
            assert_eq!(word(c, false), unicode, "Unicode {c:?}");
            assert_eq!(word(c, true), unicode && c.is_ascii(), "ASCII {c:?}");
        }
    }
}
